urlset:
{%- for file in pages -%}
    {% if not file.page.is_link and (file.page.abs_url or file.page.canonical_url) %}

         {% if file.page.canonical_url %}{{ file.page.canonical_url|e }}{% else %}{{ file.page.abs_url|e }}{% endif %}
         {% if file.page.update_date %}{{file.page.update_date}}{% endif %}
         {%- if file.page.is_homepage or file.page.url in ["en/", "de/"] %}
         {{ config.site_url }}images/og-image.jpg
         {{ config.site_url }}images/manta.png
         {{ config.site_url }}images/logo-512.png
         {{ config.site_url }}images/logo.png
         {%- endif %}

    {%- endif -%}
{% endfor %}
